export type MockLocationNotificationPermission = "not-requested" | "granted" | "denied";

/** Session-scoped Preview Mock input. `agreed_at` is always generated by the Mock server. */
export type MockLocationConsentInput = {
  terms_location: boolean;
  couponMarketingConsent: boolean;
  notificationPermission: MockLocationNotificationPermission;
};

export type MockConsumerProfileSaveInput = {
  nickname: string;
  terms_location: true;
};

export type MockConsumerProfileSaveResult = {
  profile: { nickname: string };
  terms_location: true;
  agreed_at: string;
};

export type MockLocationScenario = "outside" | "inside";
export type MockLocationFenceStatus = "unknown" | "outside" | "inside";

/** Deliberately excludes latitude/longitude: this is the only location payload exposed by the Preview Mock API. */
export type MockLocationPushEvent = {
  eventId: string;
  syntheticUserId: string;
  storePublicId: string;
  couponPublicId: string;
  idempotencyKey: string;
  title: string;
  body: string;
  createdAt: string;
};

export type MockLocationSnapshot = {
  consent: MockLocationConsentInput;
  terms_location: boolean;
  agreed_at: string | null;
  lastLocatedAt: string | null;
  locationFresh: boolean;
  fenceStatus: MockLocationFenceStatus;
  fakePushEvents: MockLocationPushEvent[];
};
